const tel = p => p ? `<a href="tel:${esc(p.replace(/[^+0-9]/g, ''))}">${esc(p)}</a>` : 'your clinic';
const page = (title, body) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)} · Northgate Dental</title><style>body{margin:0;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;background:#f3f7f6;color:#0b2b2a}main{max-width:440px;margin:0 auto;padding:40px 20px}.brand{font-weight:700;font-size:18px}.brand span{color:#137c6c}.sub{font-size:11px;letter-spacing:.15em;color:#4c6361;margin-top:2px}.card{background:#fff;border-radius:20px;padding:28px 24px;margin-top:24px;box-shadow:0 1px 2px rgba(11,43,42,.06),0 12px 32px rgba(11,43,42,.08)}h1{font-size:22px;line-height:1.25;margin:0 0 10px}p{line-height:1.55;color:#29403e;margin:0 0 12px}.visit{background:#eef5f3;border-radius:14px;padding:14px 16px;margin:16px 0;font-weight:600}.visit small{display:block;font-weight:400;color:#4c6361;margin-top:4px}button{width:100%;padding:15px;border:0;border-radius:14px;font-size:16px;font-weight:600;background:#137c6c;color:#fff;margin-top:12px;cursor:pointer}button.danger{background:#b3261e}label.choice{display:flex;gap:12px;align-items:center;border:1.5px solid #cddbd8;border-radius:14px;padding:14px 16px;margin-top:10px;font-weight:600;cursor:pointer}label.choice:has(input:checked){border-color:#137c6c;background:#eef5f3}textarea{width:100%;box-sizing:border-box;border:1.5px solid #cddbd8;border-radius:14px;padding:12px 14px;font:inherit;min-height:100px;margin-top:14px}.alert{background:#fdeeed;border:1px solid #f1c2be;border-radius:14px;padding:16px;color:#7a1d16;margin-bottom:12px}.ok{color:#137c6c;font-size:40px;line-height:1}.muted{color:#4c6361;font-size:14px}a{color:#137c6c}</style></head><body><main><div class="brand">Northgate <span>Dental</span></div><div class="sub">BACK BAY · CAMBRIDGE · QUINCY</div><div class="card">${body}</div></main></body></html>`;
const okToken = t => /^[A-Za-z0-9_-]{32}$/.test(String(t || ''));
const d = $input.first().json, t = $('Open check-in').first().json.query.t;
let html;
if (d.state === 'ok') html = page('How are you feeling?', `<h1>How are you feeling?</h1><p>After your visit:</p><div class="visit">${esc(d.service_name)}<small>${esc(d.starts_local)} · ${esc(d.clinic_name)}</small></div><form method="post"><input type="hidden" name="t" value="${esc(t)}"><label class="choice"><input type="radio" name="feeling" value="fine" checked> I am feeling fine</label><label class="choice"><input type="radio" name="feeling" value="concern"> I have a concern</label><textarea name="note" maxlength="1000" placeholder="Anything you would like us to know (optional)"></textarea><button type="submit">Send</button></form><p class="muted" style="margin-top:16px">If you have bleeding that will not stop, swelling that spreads, a fever, or trouble breathing or swallowing, call ${tel(d.clinic_phone)} now. In an emergency call 911.</p>`);
else if (d.state === 'used') html = page('Thank you', `<h1>Thank you, we already have your answer</h1><p>If anything changes, call ${tel(d.clinic_phone)}.</p>`);
else html = page('Link expired', `<h1>This link has expired</h1><p>If you have a concern about your recovery, please call your clinic.</p>`);
return [{ json: { html } }];

