const okToken = t => /^[A-Za-z0-9_-]{32}$/.test(String(t || ''));
const d = $input.first().json;
const flags = d.red_flags || [];
let html;
if (d.state !== 'recorded') html = page('Link used', `<h1>This link has already been used or has expired</h1><p>If you have a concern, please call your clinic.</p>`);
else if (flags.length) html = page('Please call us now', `<div class="alert"><strong>Please call us now on ${tel(d.clinic_phone)}.</strong> What you describe needs a clinician today.</div><p>If you have trouble breathing or swallowing, or bleeding you cannot control, call 911 or go to the nearest emergency department.</p><p class="muted">We have also alerted the clinic.</p>`);
else if ($('Check-in sent').first().json.body.feeling === 'concern') html = page('Thank you', `<div class="ok">&#10003;</div><h1>Thank you for telling us</h1><p>A member of our clinical team will contact you today. If it gets worse before then, call ${tel(d.clinic_phone)}.</p>`);
else html = page('Thank you', `<div class="ok">&#10003;</div><h1>Glad to hear it</h1><p>Thank you for letting us know. Take care.</p>`);
return [{ json: { html } }];
